"""Extract title, first page text, and metadata from all PDFs in workspace."""
import os
import subprocess
import re
import json
import sys
from pathlib import Path

WORKDIR = Path("/Users/wangjinhua/Library/Caches/VistaExperiments/formal-task005-local-3x3-minimaxm3-20260824-03-noskill-replicate-02-attempt-01/workspace")
PDFTOTEXT = "/Users/wangjinhua/.cache/codex-runtimes/codex-primary-runtime/dependencies/native/poppler/poppler/bin/pdftotext"


def extract_pdf_text(pdf_path, max_pages=3):
    """Extract text from first N pages of a PDF."""
    try:
        result = subprocess.run(
            [PDFTOTEXT, "-f", "1", "-l", str(max_pages), str(pdf_path), "-"],
            capture_output=True, text=True, timeout=60
        )
        return result.stdout
    except Exception as e:
        return f"ERROR: {e}"


