    out_dir = Path("/tmp/pdf_extract")
    out_dir.mkdir(exist_ok=True)

    results = {}
    for pdf in pdfs:
        name = pdf.name
        info = pdf_info(pdf)
        text = extract_pdf_text(pdf, max_pages=2)
