        # keep title and first 1000 chars
        results[name] = {
            "info": info,
            "text_first_1500": text[:1500]
        }
    # dump JSON
    Path("/tmp/pdf_meta.json").write_text(json.dumps(results, indent=2))
    print(f"Processed {len(pdfs)} PDFs")


if __name__ == "__main__":
