#!/usr/bin/env python3
"""Extract text from DOCX and PPTX in workspace."""
import zipfile
import re
import json
from pathlib import Path
import xml.etree.ElementTree as ET

WORKDIR = Path("/Users/wangjinhua/Library/Caches/VistaExperiments/formal-task005-local-3x3-minimaxm3-20260824-03-noskill-replicate-02-attempt-01/workspace")
OUTDIR = WORKDIR / "_work"
NS = "{http://schemas.openxmlformats.org/wordprocessingml/2006/main}"
NS_P = "{http://schemas.openxmlformats.org/presentationml/2006/main}"


def extract_docx_text(docx_path):
    """Extract text from docx file."""
    text_parts = []
    try:
        with zipfile.ZipFile(docx_path, 'r') as z:
            with z.open("word/document.xml") as f:
                tree = ET.parse(f)
                root = tree.getroot()
                for para in root.iter(NS + "p"):
                    runs = []
                    for t in para.iter(NS + "t"):
                        if t.text:
                            runs.append(t.text)
                    if runs:
                        text_parts.append("".join(runs))
    except Exception as e:
        return f"ERROR: {e}"
    return "\n".join(text_parts)


def extract_pptx_text(pptx_path):
    """Extract text from pptx file."""
    text_parts = []
    try:
        with zipfile.ZipFile(pptx_path, 'r') as z:
            slide_files = sorted([n for n in z.namelist() if n.startswith("ppt/slides/slide") and n.endswith(".xml")])
            for sf in slide_files:
                with z.open(sf) as f:
                    tree = ET.parse(f)
                    root = tree.getroot()
                    slide_text = []
                    for t in root.iter("{http://schemas.openxmlformats.org/drawingml/2006/main}t"):
                        if t.text:
                            slide_text.append(t.text)
                    if slide_text:
                        text_parts.append(f"=== {sf} ===\n" + "\n".join(slide_text))
    except Exception as e:
        return f"ERROR: {e}"
    return "\n\n".join(text_parts)


def main():
    out_dir = OUTDIR / "other_text"
    out_dir.mkdir(exist_ok=True)

    results = {}
    for ext, extractor in [("*.docx", extract_docx_text), ("*.pptx", extract_pptx_text)]:
        for f in WORKDIR.glob(ext):
            text = extractor(f)
            (out_dir / (f.name + ".txt")).write_text(text[:8000])
            results[f.name] = text[:3000]
    (OUTDIR / "other_meta.json").write_text(json.dumps(results, indent=2))
    print(f"Processed {len(results)} other files")


if __name__ == "__main__":
    main()
